-- Generated by drizzle-kit, then edited by hand in one place: attachments_location_id_uq is added
-- before the foreign keys that reference it (drizzle-kit put it after extractions_attachment_fk).
CREATE TABLE "extractions" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7() NOT NULL,
	"location_id" uuid NOT NULL,
	"attachment_id" uuid NOT NULL,
	"thing_id" uuid,
	"purchase_id" uuid,
	"meter_id" uuid,
	"mode" text NOT NULL,
	"attempt" integer DEFAULT 1 NOT NULL,
	"status" text DEFAULT 'queued' NOT NULL,
	"status_reason" text,
	"paused_until" timestamp with time zone,
	"llm_call_id" uuid,
	"result" jsonb,
	"applied" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"requested_by" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"row_version" integer DEFAULT 1 NOT NULL,
	"change_seq" bigint,
	CONSTRAINT "extractions_location_id_uq" UNIQUE("location_id","id"),
	CONSTRAINT "extractions_attempt_uq" UNIQUE("attachment_id","attempt"),
	CONSTRAINT "extractions_mode_chk" CHECK ("mode" IN ('thing', 'receipt', 'label', 'reading')),
	CONSTRAINT "extractions_status_chk" CHECK ("status" IN ('queued', 'running', 'succeeded', 'failed', 'paused_budget', 'waiting_provider', 'no_provider', 'superseded')),
	CONSTRAINT "extractions_attempt_chk" CHECK (attempt BETWEEN 1 AND 50),
	CONSTRAINT "extractions_status_reason_chk" CHECK (char_length(status_reason) <= 60),
	CONSTRAINT "extractions_one_draft_chk" CHECK (num_nonnulls(thing_id, purchase_id, meter_id) <= 1),
	CONSTRAINT "extractions_result_chk" CHECK (result IS NULL OR jsonb_typeof(result) = 'object'),
	CONSTRAINT "extractions_applied_chk" CHECK (jsonb_typeof(applied) = 'object')
);
--> statement-breakpoint
CREATE TABLE "file_text" (
	"file_id" uuid PRIMARY KEY NOT NULL,
	"location_id" uuid NOT NULL,
	"source" text NOT NULL,
	"text" text NOT NULL,
	"tsv" "tsvector" GENERATED ALWAYS AS (to_tsvector('simple', kept.search_text(left(text, 100000)))) STORED,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "file_text_source_chk" CHECK ("source" IN ('pdf', 'extraction')),
	CONSTRAINT "file_text_text_chk" CHECK (char_length(text) <= 200000)
);
