	CONSTRAINT "inbox_items_code_chk" CHECK (code ~ '^[0-9A-HJKMNP-TV-Z]{6}$'),
	CONSTRAINT "inbox_items_payload_chk" CHECK (jsonb_typeof(payload) = 'object'),
	CONSTRAINT "inbox_items_resolved_chk" CHECK ((resolved_at IS NULL) = (resolution IS NULL)),
