CREATE TABLE "import_runs" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7() NOT NULL,
	"location_id" uuid NOT NULL,
	"source" text NOT NULL,
	"source_version" text,
	"status" text DEFAULT 'draft' NOT NULL,
	"mapping" jsonb DEFAULT '{}'::jsonb NOT NULL,
