	CONSTRAINT "import_runs_rows_chk" CHECK (rows IS NULL OR jsonb_typeof(rows) = 'array'),
	CONSTRAINT "import_runs_progress_chk" CHECK (progress >= 0 AND (total IS NULL OR progress <= total)),
	CONSTRAINT "import_runs_error_chk" CHECK (char_length(error) <= 500)
);
